import React from "react";
import '../global'


class Settings extends React.Component {
  state = {
    key: global.config.key
  };
  
  handleChange(event) {
    var value = event.target.value;
    global.config.key = event.target.value;
    this.setState({
      fullName: value,
    });
  }

  render() {
    return (
      <div className = "Col80">
          Entrer la nouvelle clé API:
          <input
            type="text"
            value={global.config.key}
            onChange={event => this.handleChange(event)}
          />
          <button onClick>X</button>
      </div>
    );
  }
}

export const key = true;

console.log(global.config.key);
export default Settings;
